/**
 * Help and usage rendering, mirroring `argparse.HelpFormatter`.
 *
 * The layout depends on the terminal width, which the interpreter reads from
 * `COLUMNS` and falls back to 80 for, so the same lookup happens here.
 */

const INDENT_INCREMENT = 2;
const MAX_HELP_POSITION = 24;
const USAGE_PREFIX = 'usage: ';

/** Terminal width argparse formats against: `shutil.get_terminal_size().columns - 2`. */
export function terminalWidth() {
  const declared = process.env.COLUMNS;
  if (declared !== undefined) {
    // Python accepts any integer literal here and ignores non-positive values.
    if (/^[+-]?\d+$/.test(declared.trim())) {
      let columns = 0;
      const body = declared.trim().replace(/^\+/, '');
      const negative = body.startsWith('-');
      for (const ch of negative ? body.slice(1) : body) {
        columns = columns * 10 + (ch.charCodeAt(0) - 48);
      }
      if (negative) columns = -columns;
      if (columns > 0) return columns - 2;
    }
  }
  if (process.stdout.isTTY && process.stdout.columns > 0) {
    return process.stdout.columns - 2;
  }
  return 78;
}

/** Greedy wrap, equivalent to `textwrap.wrap` for the short help strings used here. */
function wrapText(text, width) {
  const words = text.split(/\s+/).filter((word) => word !== '');
  const lines = [];
  let current = '';
  for (const word of words) {
    if (current === '') {
      current = word;
    } else if (current.length + 1 + word.length <= width) {
      current += ` ${word}`;
    } else {
      lines.push(current);
      current = word;
    }
  }
  if (current !== '') lines.push(current);
  return lines.length === 0 ? [''] : lines;
}

/** `--a A` / `-h, --help` -- how an action is spelled in the options list. */
export function formatInvocation(action) {
  if (action.nargs === 0) return action.optionStrings.join(', ');
  return action.optionStrings.map((opt) => `${opt} ${action.metavar}`).join(', ');
}

/** The bracketed form used inside the usage line. */
function formatUsagePart(action) {
  const invocation =
    action.nargs === 0
      ? action.optionStrings[0]
      : `${action.optionStrings[0]} ${action.metavar}`;
  return action.required ? invocation : `[${invocation}]`;
}

/**
 * Wrap a list of usage parts, reproducing argparse's `get_lines` helper.
 * `prefix` is only passed for the first block, whose first line is unindented.
 */
function getLines(parts, indent, textWidth, prefix) {
  const lines = [];
  let line = [];
  let lineLength = prefix === null ? indent.length - 1 : prefix.length - 1;
  for (const part of parts) {
    if (lineLength + 1 + part.length > textWidth && line.length > 0) {
      lines.push(indent + line.join(' '));
      line = [];
      lineLength = indent.length - 1;
    }
    line.push(part);
    lineLength += 1 + part.length;
  }
  if (line.length > 0) lines.push(indent + line.join(' '));
  if (prefix !== null && lines.length > 0) lines[0] = lines[0].slice(indent.length);
  return lines;
}

/** The `usage: ...` block, without its trailing blank line. */
export function formatUsage(prog, actions, width) {
  const parts = actions.map(formatUsagePart);
  let usage = [prog, ...parts].join(' ');
  const textWidth = width;

  if (USAGE_PREFIX.length + usage.length > textWidth) {
    if (USAGE_PREFIX.length + prog.length <= 0.75 * textWidth) {
      const indent = ' '.repeat(USAGE_PREFIX.length + prog.length + 1);
      usage = getLines([prog, ...parts], indent, textWidth, USAGE_PREFIX).join('\n');
    } else {
      // The program name is too wide to share its line with the options.
      const indent = ' '.repeat(USAGE_PREFIX.length);
      usage = [prog, ...getLines(parts, indent, textWidth, null)].join('\n');
    }
  }
  return `${USAGE_PREFIX}${usage}\n`;
}

/** The complete `--help` text, terminated by exactly one newline. */
export function formatHelp(prog, actions, width) {
  const invocations = actions.map(formatInvocation);
  const actionMaxLength = Math.max(
    ...invocations.map((text) => text.length + INDENT_INCREMENT),
  );
  const maxHelpPosition = Math.min(
    MAX_HELP_POSITION,
    Math.max(width - 20, INDENT_INCREMENT * 2),
  );
  const helpPosition = Math.min(actionMaxLength + 2, maxHelpPosition);
  const actionWidth = helpPosition - INDENT_INCREMENT - 2;

/**
 * Traceback rendering for exceptions that reach the top level.
 *
 * Two details matter for fidelity:
 *
 *  - The source line is looked up through the equivalent of `linecache`, i.e.
 *    the recorded file name resolved against the working directory.  The
 *    reference build ships no sources, so the line appears only when a
 *    `test20.py` happens to sit next to the caller -- and then it is that
 *    file's text that gets echoed.
 *  - When the line is available it is followed by the fine-grained anchors
 *    added in 3.11: `^` under the failing operator, `~` under the rest of the
 *    expression, with columns taken relative to the stripped line.
 */

import { readFileSync } from 'node:fs';

import { writeStderr } from './stdio.mjs';

const SOURCE_INDENT = '    ';

/** @type {Map<string, string[]|null>} */
const lineCache = new Map();

/** The requested source line, or null when the file cannot be consulted. */
function lookupSourceLine(file, lineNumber) {
  if (!lineCache.has(file)) {
    try {
      lineCache.set(file, readFileSync(file, 'utf8').split(/\r\n|\r|\n/));
    } catch {
      lineCache.set(file, null);
    }
  }
  const lines = lineCache.get(file);
  if (lines === null) return null;
  const line = lines[lineNumber - 1];
  return line === undefined || line === '' ? null : line;
}

/**
 * Build the anchor line for a span, in columns relative to the stripped line.
 *
 * @param {[number, number]} span  Half-open column range of the expression.
 * @param {[number, number]|null} operator  Column range of the operator token
 *   for a binary operation; `null` marks the whole span with carets.
 */
export function anchorLine(span, operator) {
  const [start, end] = span;
  let marks;
  if (operator === null) {
    marks = '^'.repeat(end - start);
  } else {
    const [operatorStart, operatorEnd] = operator;
    marks =
      '~'.repeat(operatorStart - start) +
      '^'.repeat(operatorEnd - operatorStart) +
      '~'.repeat(end - operatorEnd);
  }
  return ' '.repeat(SOURCE_INDENT.length + start) + marks;
}

/**
 * Render and emit a traceback.
 *
 * @param {{file: string, line: number, span: [number, number],
 *          operator: [number, number]|null}} origin  The `<module>` frame.
 * @param {{file: string, line: number, name: string}[]} frames
 *   Library frames below it, outermost first.  The reference build has no
 *   source for those, so only their headers are printed.
 * @param {string} exceptionLine  The trailing `Type: message` line.
 */
export function printTraceback(origin, frames, exceptionLine) {
  let out = 'Traceback (most recent call last):\n';
  out += `  File "${origin.file}", line ${origin.line}, in <module>\n`;

  const rawLine = lookupSourceLine(origin.file, origin.line);
  if (rawLine !== null) {
    const stripped = rawLine.trim();
    const indentWidth = rawLine.length - rawLine.trimStart().length;
    out += `${SOURCE_INDENT}${stripped}\n`;

    const span = [origin.span[0] - indentWidth, origin.span[1] - indentWidth];
    const operator =
      origin.operator === null
        ? null
        : [origin.operator[0] - indentWidth, origin.operator[1] - indentWidth];
    // Anchors are suppressed only when they would cover the whole line and
    // carry no operator detail.
    if (span[1] - span[0] < stripped.length || operator !== null) {
      out += `${anchorLine(span, operator)}\n`;
    }
  }

  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  }
  out += `${exceptionLine}\n`;
  writeStderr(out);
}
